import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../components/Toast';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const { addToast } = useToast();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(email, password);
      addToast('Welcome back! Signed in successfully.', 'success');
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed. Please check your credentials.');
      addToast('Login failed. Please check credentials.', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-fullscreen-container">
      <div className="auth-split-box">
        {/* Left Side: Brand Promo / Showcase */}
        <div className="auth-feature-side">
          <div className="auth-brand-badge">⚡ ResumeCraft Pro</div>
          <h2 className="auth-feature-title">Build Resumes That Land Dream Interviews.</h2>
          <p className="auth-feature-desc">
            Design recruiter-ready, ATS-compliant resumes with real-time visual feedback, power action verbs, and proven template layouts.
          </p>

          <div className="auth-perks-list">
            <div className="perk-item">
              <span className="perk-icon">⏱️</span>
              <div>
                <strong>Executive Timeline Layouts</strong>
                <p>Highlight your career trajectory with dual-axis chronological timelines.</p>
              </div>
            </div>
            <div className="perk-item">
              <span className="perk-icon">📊</span>
              <div>
                <strong>Live ATS Score Meter</strong>
                <p>Get actionable suggestions to pass applicant tracking systems with flying colors.</p>
              </div>
            </div>
            <div className="perk-item">
              <span className="perk-icon">📥</span>
              <div>
                <strong>Pixel-Perfect PDF Generation</strong>
                <p>One-click instant PDF download formatted for print and digital screening.</p>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Sign In Form */}
        <div className="auth-form-side">
          <form className="auth-card-modern" onSubmit={handleSubmit}>
            <div className="auth-card-header">
              <h3>Welcome Back</h3>
              <p>Sign in to access your resumes and career documents</p>
            </div>

            {error && <div className="error-banner">{error}</div>}

            <div className="auth-field-group">
              <label>Email Address</label>
              <div className="input-icon-wrapper">
                <span className="input-icon">✉️</span>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="name@company.com"
                  required
                />
              </div>
            </div>

            <div className="auth-field-group">
              <label>Password</label>
              <div className="input-icon-wrapper">
                <span className="input-icon">🔒</span>
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  required
                />
                <button
                  type="button"
                  className="btn-password-toggle"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? '🙈' : '👁️'}
                </button>
              </div>
            </div>

            <button type="submit" className="btn-auth-submit" disabled={loading}>
              {loading ? 'Signing In…' : 'Sign In →'}
            </button>

            <div className="auth-card-footer">
              <p>Don't have an account? <Link to="/register" className="auth-link-bold">Create Account Free</Link></p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
